function trendColor(kind: TrendKind) {
  return kind === "bad" ? "text-[#B3261E]" : "text-[#067647]";
}

function Trend({ value, kind }: { value: string; kind: TrendKind }) {
  const Arrow = kind === "down-good" ? IconArrowDown : IconArrowUp;
  return (
    <span
      className={cn(
        "inline-flex items-center gap-1 self-end whitespace-nowrap text-[10px] leading-[14px]",
        trendColor(kind),
      )}
    >
      <span className="inline-flex items-center gap-0.5 font-medium">
        <Arrow size={12} />
        {value}
      </span>
      <span className="font-normal">vs last month</span>
    </span>
  );
}

function ModeToggle({
  mode,
  onChange,
}: {
  mode: LeadMode;
  onChange: (m: LeadMode) => void;
}) {
  const options: { id: LeadMode; label: string }[] = [
    { id: "open", label: "Open Leads" },
    { id: "closed", label: "Closed Leads" },
    { id: "both", label: "Both" },
  ];

  return (
    <div className="inline-flex rounded-lg border border-[rgba(13,24,61,0.15)] bg-white p-1">
      {options.map((opt) => (
        <button
          key={opt.id}
          type="button"
          onClick={() => onChange(opt.id)}
          className={cn(
            "rounded-md px-2.5 py-1 text-xs font-medium leading-[15.6px] transition-colors duration-200",
            mode === opt.id
              ? "bg-[rgba(246,134,31,0.08)] text-icr-orange ring-1 ring-[rgba(255,255,255,0.75)]"
              : "text-[rgba(29,54,80,0.8)]",
          )}
        >
          {opt.label}
        </button>
      ))}
    </div>
  );
}

function CollapseToggle({
  open,
  onClick,
  accent,
}: {
  open: boolean;
  onClick: () => void;
  accent?: boolean;
}) {
  return (
    <button
      type="button"
      aria-expanded={open}
      onClick={onClick}
      className={cn(
        "inline-flex shrink-0 items-center justify-center rounded p-1.5 transition-colors duration-200",
        accent || open
          ? "bg-[rgba(246,134,31,0.12)] text-icr-orange"
          : "bg-[#F8F9FA] text-icr-navy",
      )}
    >
      <span
        className={cn(
          "inline-flex transition-transform duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]",
          open && "rotate-180",
        )}
      >
        <IconChevronDown size={12} />
      </span>
    </button>
  );
}

function MetricColumn({
  metric,
  open,
  onToggle,
}: {
  metric: Metric;
  open: boolean;
  onToggle: () => void;
}) {
  return (
    <div className="flex min-w-0 flex-1 flex-col gap-3 border-r border-[#DBDDE2] px-4 pb-4 first:pl-0 last:border-r-0 last:pr-0 max-[900px]:border-r-0">
      <div className="flex items-center justify-between gap-2 py-1">
        <div className="min-w-0 flex-1 text-sm font-medium leading-[18.9px] text-[rgba(29,54,80,0.8)]">
          {metric.title}
        </div>
        <CollapseToggle open={open} onClick={onToggle} accent={open} />
      </div>

      <div className="flex flex-col gap-3">
        <div className="flex flex-wrap items-end gap-2">
          <div className="text-2xl font-medium leading-[32.4px] text-icr-navy">
            {metric.value}
          </div>
          {metric.aside ? (
            <div className="pb-0.5 text-sm leading-[14px] text-[#475467]">
              {metric.aside}
            </div>
          ) : null}
          <Trend value={metric.trend} kind={metric.trendKind} />
        </div>
        <div className="flex items-center gap-1 text-[10px] leading-[14px] text-[#475467]">
          <span className="font-normal">Baseline Median</span>
          <span className="font-medium">{metric.baseline}</span>
        </div>
      </div>

      <div
        className={cn(
          "grid transition-[grid-template-rows] duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]",
          open ? "grid-rows-[1fr]" : "grid-rows-[0fr]",
        )}
      >
        <div className="min-h-0 overflow-hidden">
          <div
            className={cn(
              "flex flex-col gap-2 border-t border-[#DBDDE2] pt-3 transition-opacity duration-300",
              open ? "opacity-100" : "opacity-0",
            )}
          >
            <div className="text-[10px] font-medium tracking-wide text-[#6A7282] uppercase">
              Current month breakdown
            </div>
            {metric.hint ? (
              <div className="text-xs text-icr-navy">{metric.hint}</div>
            ) : null}
            {metric.items.map((item) => (
              <div
                className="flex items-start justify-between gap-2 text-xs leading-[18px] text-icr-navy"
                key={`${metric.title}-${item.label}`}
              >
                <div>
                  <strong className="mr-1 font-semibold">{item.value}</strong>
                  {item.label}
                </div>
                {item.right ? (
                  <div
                    className={cn(
                      "whitespace-nowrap text-right text-[#475467]",
                      item.trend && trendColor(item.trend),
                    )}
                  >
                    {item.right}
                  </div>
                ) : null}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

function SummaryPanel({
  title,
  metrics,
}: {
  title: string;
  metrics: Metric[];
}) {
  const [openKeys, setOpenKeys] = useState<string[]>([]);
  const [breakdown, setBreakdown] = useState<Breakdown>("department");
  const anyOpen = openKeys.length > 0;
  const allOpen = openKeys.length === metrics.length;

  function toggleOne(title: string) {
    setOpenKeys((curr) =>
      curr.includes(title) ? curr.filter((t) => t !== title) : [...curr, title],
    );
  }

  function toggleAll() {
    setOpenKeys(allOpen ? [] : metrics.map((m) => m.title));
  }

  return (
    <div className="flex w-full flex-col rounded-[14px] border border-[#DBDDE2] bg-white pt-3">
      <div className="flex flex-col gap-4 px-3 pb-2">
        <div className="flex h-8 items-center justify-between gap-3">
          <h3 className="m-0 text-sm font-medium leading-[17.5px] text-icr-navy">
            {title}
          </h3>
          <div
            className={cn(
              "grid transition-[grid-template-rows,opacity] duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]",
              anyOpen
                ? "grid-rows-[1fr] opacity-100"
                : "pointer-events-none grid-rows-[0fr] opacity-0",
            )}
          >
            <div className="min-h-0 overflow-hidden">
              <div className="inline-flex overflow-hidden rounded-lg border border-[rgba(13,24,61,0.15)] bg-white">
                <button
                  type="button"
                  onClick={() => setBreakdown("department")}
                  className={cn(
                    "h-8 px-3 text-xs font-medium transition-colors duration-200",
                    breakdown === "department"
                      ? "bg-[rgba(246,134,31,0.08)] text-icr-orange"
                      : "text-[rgba(29,54,80,0.8)]",
                  )}
                >
                  Breakdown by Department
                </button>
                <button
                  type="button"
                  onClick={() => setBreakdown("region")}
                  className={cn(
                    "h-8 border-l border-[rgba(13,24,61,0.15)] px-3 text-xs font-medium transition-colors duration-200",
                    breakdown === "region"
                      ? "bg-[rgba(246,134,31,0.08)] text-icr-orange"
                      : "text-[rgba(29,54,80,0.8)]",
                  )}
                >
                  Breakdown by Region
                </button>
              </div>
            </div>
          </div>
        </div>

        <div className="flex items-start max-[1100px]:flex-col">
          {metrics.map((m) => (
            <MetricColumn
              key={m.title}
              metric={m}
              open={openKeys.includes(m.title)}
              onToggle={() => toggleOne(m.title)}
            />
          ))}
        </div>
      </div>

      <div className="flex h-[49px] items-center rounded-b-[14px] border-t border-[#DBDDE2] px-3 py-2">
        <button
          type="button"
          onClick={toggleAll}
          className="inline-flex items-center gap-1.5 text-xs font-medium leading-[17.44px] text-icr-orange"
        >
          {anyOpen ? "Hide Current month breakdown" : "View Current month breakdown"}
          <span
            className={cn(
              "inline-flex transition-transform duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]",
              anyOpen && "rotate-180",
            )}
          >
            <IconChevronDown size={14} />
          </span>
        </button>
      </div>
    </div>
  );
}

export function SummarySection() {
  const [mode, setMode] = useState<LeadMode>("both");
  const showOpen = mode === "open" || mode === "both";
  const showClosed = mode === "closed" || mode === "both";

  return (
    <section className="flex flex-col gap-4 rounded-[14px] border border-[#DBDDE2] bg-white p-4">
      <div className="flex items-start justify-between gap-2.5">
        <div className="min-w-0 flex-1">
          <h2 className="m-0 text-base font-medium leading-5 text-icr-navy">
            Summary of current workload and completed outcomes
          </h2>
          <p className="mt-0 mb-0 text-xs leading-[16.8px] text-[rgba(29,54,80,0.65)]">
            Track current performance against last month and the median over the
            previous 6 months.
          </p>
        </div>
        <ModeToggle mode={mode} onChange={setMode} />
      </div>

      <div className="flex flex-col gap-4">
        {showOpen ? (
          <SummaryPanel title="Open Leads this month" metrics={openMetrics} />
        ) : null}
        {showClosed ? (
          <SummaryPanel title="Closed Leads this month" metrics={closedMetrics} />
        ) : null}
      </div>
    </section>
  );
}
